def is_time_between(time_str, start_str, end_str):
    time = datetime.strptime(time_str, "%H:%M")
    start = datetime.strptime(start_str, "%H:%M")
    end = datetime.strptime(end_str, "%H:%M")
    return start <= time <= end

def get_next_available_time(schedule, current_time):
    current_time = datetime.strptime(current_time, "%H:%M")
    next_time = None
    for start, end in schedule:
        start_time = datetime.strptime(start, "%H:%M")
        end_time = datetime.strptime(end, "%H:%M")
        if start_time > current_time:
            if next_time is None or start_time < next_time:
                next_time = start_time
        elif end_time > current_time:
            if next_time is None or end_time < next_time:
                next_time = end_time
    return next_time.strftime("%H:%M") if next_time else "true"

def check_availability(schedule, current_time):
    if not schedule:
        return "true"
    current_time = datetime.strptime(current_time, "%H:%M")
    for start, end in schedule:
        start_time = datetime.strptime(start, "%H:%M")
        end_time = datetime.strptime(end, "%H:%M")
        if start_time <= current_time <= end_time:
            return get_next_available_time(schedule, current_time)
    return "true"

