def encode_digit(digit, key_digit):
    return (digit + key_digit) % 26

def encode_message(message, key):
    key_digits = [int(d) for d in str(key)]
    encoded_message = []
    key_index = 0
    for char in message:
        digit = letter_to_number(char)
        encoded_digit = encode_digit(digit, key_digits[key_index])
        encoded_message.append(encoded_digit)
        key_index = (key_index + 1) % len(key_digits)
    return encoded_message

def encode(message, key):
    return encode_message(message, key)

